def _td_paint_meter():
    with tdapp.batch():
        meter.fill(0, 0, 64, 20, " ", -1, -1)
        meter.gradient(0, 0, 128, 40, [0, 0, 80], [0, 120, 255], across=False)
        meter.draw_text(4, 2, "PIXEL CONTROLS", 231, bg=tdui.CLEAR, scale=1, small=True)
        meter.bar(
            4,
            14,
            80,
            4,
            value=65,
            maximum=100,
            color=40,
            track=237,
            edge=120,
            radius=1,
            gradient={
                "rgb1": [0, 190, 255],
                "rgb2": [0, 32, 112],
                "across": True,
            },
        )
        meter.rect(
            4,
            22,
            20,
            6,
            40,
            radius=2,
            outline=False,
            gradient={
                "rgb1": [0, 190, 255],
                "rgb2": [0, 32, 112],
                "across": False,
            },
        )
        meter.circle(
            32,
            25,
            3,
            196,
            outline=False,
            gradient={
                "rgb1": [0, 190, 255],
                "rgb2": [0, 32, 112],
                "across": False,
            },
        )
        meter.line(4, 30, 100, 30, 40)
        global apply_button
        if apply_button is None:
            apply_button = meter.button(
                2,
                16,
                14,
                3,
                "Apply",
                color=25,
                down=18,
                rim=32,
                fg=231,
                radius=2,
                scale=0,
                gradient={
                    "rgb1": [0, 190, 255],
                    "rgb2": [0, 32, 112],
                    "across": False,
                },
            )
        else:
            apply_button.draw()
        global second_button
        if second_button is None:
            second_button = meter.button(
                18,
                16,
                14,
                3,
                "Second",
                color=25,
                down=18,
                rim=32,
                fg=231,
                radius=0,
                scale=0,
                gradient={
                    "rgb1": [0, 190, 255],
                    "rgb2": [0, 32, 112],
                    "across": False,
                },
            )
        else:
            second_button.draw()

_td_page_names_win = ["Main"]


def _td_show_win(name):
    with tdapp.batch():
        _td_apply_win(name)


def _td_apply_win(name):
    if name not in _td_page_names_win:
        raise ValueError("unknown page")
    tdapp.show_canvases(win, name)


def show_page(name, window=None):
    if window is None:
        window = win
    if window is win:
        return _td_show_win(name)
    raise ValueError("unknown window")

# Event handlers: keep these quick and nonblocking.
# Wire callbacks after their definitions.
tdapp.register_canvas(win, 0, meter, meter, "Main", 0, 0, 0, _td_paint_meter, True, None)
_td_show_win("Main")

tdui.run()

